// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for ru-chat-send: dry run sends 0, live sends once, crash resume, caps, halt
// Flo: mock chat page > send in each mode > assert page state and store rows
// I/O: html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const snd = @import("ru-chat-send.zig"); const sess = @import("ru-sess-ctxz.zig"); const data = @import("st-stat-data.zig"); const conf = @import("cf-conf-load.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
const NOON: i64 = 100 * 86400000 + 12 * 3600000;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
fn cfgOf() conf.Conf { var cfg: conf.Conf = .{}; cfg.type_dely_msec = .{ 1, 2 }; cfg.warm_dayz_coun = 0; cfg.retr_coun_maxz = 2; return cfg; }
const Rig = struct { tmpz: std.testing.TmpDir, mok: mock.Mock, aren: std.heap.ArenaAllocator, sto: data.Stor,
fn up(self: *Rig, buff: []u8, html: []const u8) !void { self.tmpz = std.testing.tmpDir(.{}); self.mok = try mock.start(T.allocator, T.io, try profOf(&self.tmpz, buff), html); self.aren = std.heap.ArenaAllocator.init(T.allocator); self.sto = try data.Stor.open(T.allocator, ":memory:"); }
fn down(self: *Rig) void { self.sto.close(); self.aren.deinit(); self.mok.stop(); self.tmpz.cleanup(); }
fn ses(self: *Rig, cfg: conf.Conf, mode: sess.Mode) sess.Sess { var out = sess.Sess.init(T.allocator, T.io, self.aren.allocator(), cfg, &self.sto, self.mok.conn, mode); out.fast = true; out.fake_ms = NOON; out.job = "send"; return out; }
fn sentN(self: *Rig) !i64 { const txt = try snap.evalStr(self.aren.allocator(), self.mok.conn, "sent.length"); return try std.fmt.parseInt(i64, txt, 10); } };
test "read-only mode refuses to send, empty text is BadJob" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .read); try T.expectError(error.BadUsage, snd.sendText(&ses, "Mom", "hi")); var live = rig.ses(cfgOf(), .live); try T.expectError(error.BadJob, snd.sendText(&live, "Mom", "   ")); try T.expectError(error.BadJob, snd.sendText(&live, "", "hi")); try T.expectEqual(@as(i64, 0), try rig.sentN()); }
test "dry run previews, sends 0, changes no counters, unknown chat is NoElem" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .dry); try T.expect(try snd.sendText(&ses, "Mom", "Hello Mom") == .dry); try T.expectEqual(@as(i64, 0), try rig.sentN()); const sta = try rig.sto.statGet(T.allocator, NOON); try T.expectEqual(@as(u32, 0), sta.day_cnt); const rows = try rig.sto.logTail(rig.aren.allocator(), 3); try T.expect(std.mem.startsWith(u8, rows[rows.len - 1].msg, "PREVIEW Mom: Hello Mom")); try T.expectError(error.NoElem, snd.sendText(&ses, "Nobody", "x")); }
test "M5 live send once: Vietnamese text lands, counted once, duplicate is skipped" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .live); try T.expect(try snd.sendText(&ses, "mom", "Chào Mom, tối nay 7h nhé") == .sent); try T.expectEqual(@as(i64, 1), try rig.sentN()); try T.expectEqualStrings("Mom|Chào Mom, tối nay 7h nhé", try snap.evalStr(rig.aren.allocator(), rig.mok.conn, "sent[0]")); ses.fake_ms = NOON + 60000; try T.expect(try snd.sendText(&ses, "Mom", "Chào Mom, tối nay 7h nhé") == .dup); try T.expectEqual(@as(i64, 1), try rig.sentN()); const sta = try rig.sto.statGet(T.allocator, NOON + 70000); try T.expectEqual(@as(u32, 1), sta.day_cnt); }
test "crash after typing: resume sees the message and does not send again" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .live); _ = try snap.evalStr(rig.aren.allocator(), rig.mok.conn, "openChat('Mom');box.innerText='Yo';sendMsg();sent.length"); try T.expect(try rig.sto.sendBegin("Mom", "Yo", NOON) == .fresh); try T.expect(try snd.sendText(&ses, "Mom", "Yo") == .sent); try T.expectEqual(@as(i64, 1), try rig.sentN()); try T.expect(try rig.sto.sendBegin("Mom", "Yo", NOON) == .dup); }
test "crash before typing: resume sends it once" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .live); try T.expect(try rig.sto.sendBegin("Mom", "Later", NOON) == .fresh); try T.expect(try snd.sendText(&ses, "Mom", "Later") == .sent); try T.expectEqual(@as(i64, 1), try rig.sentN()); }
test "hour cap stops the second send and leaves the page untouched" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var cfg = cfgOf(); cfg.capz_send_hour = 1; cfg.capz_send_dayz = 5; var ses = rig.ses(cfg, .live); try T.expect(try snd.sendText(&ses, "Mom", "one") == .sent); ses.fake_ms = NOON + 600000; try T.expectError(error.CapHit, snd.sendText(&ses, "Mom", "two")); try T.expectEqual(@as(i64, 1), try rig.sentN()); }
test "min gap between sends is waited out, not skipped" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var ses = rig.ses(cfgOf(), .live); try T.expect(try snd.sendText(&ses, "Mom", "a1") == .sent); const t1 = ses.fake_ms; try T.expect(try snd.sendText(&ses, "Mom", "a2") == .sent); try T.expect(ses.fake_ms - t1 >= 2900); try T.expectEqual(@as(i64, 2), try rig.sentN()); }
test "M4 live: a lock page halts the send, flag stored, nothing typed" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.lock); defer rig.down(); var ses = rig.ses(cfgOf(), .live); try T.expectError(error.Halted, snd.sendText(&ses, "Mom", "hi")); const why = try rig.sto.haltGet(T.allocator); try T.expect(why != null); T.allocator.free(why.?); try T.expectError(error.Halted, snd.sendText(&ses, "Mom", "hi")); }
test "quiet hours stop a live send" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff, fixt.chat); defer rig.down(); var cfg = cfgOf(); cfg.loca_utcz_mins = 0; var ses = rig.ses(cfg, .live); ses.fake_ms = 100 * 86400000 + 3600000; try T.expectError(error.QuietHrs, snd.sendText(&ses, "Mom", "hi")); try T.expectEqual(@as(i64, 0), try rig.sentN()); }
